import urllib.request, json
targets = {
    "anyhow":"1.0.86","tokio":"1.38.0","prost":"0.12.6",
    "tokio-util":"0.7.11","data-encoding":"2.6.0","internet-packet":"0.2.1",
}
for crate,tv in targets.items():
    url=f"https://crates.io/api/v1/crates/{crate}/{tv}"
    req=urllib.request.Request(url,headers={"User-Agent":"dep-check"})
    try:
        d=json.load(urllib.request.urlopen(req,timeout=20))
        v=d["version"]
        print(f"{crate} {tv}: EXISTS, created {v['created_at'][:10]}, yanked={v['yanked']}")
    except Exception as e:
        print(f"{crate} {tv}: ERROR {e}")
EOF

